import { compose } from '@adonisjs/core/helpers'
import { BaseModel, column } from '@adonisjs/lucid/orm'
import { test } from '@japa/runner'
import { E_UNKNOWN_PERMISSION } from '../src/errors.ts'
import { withPermissions } from '../src/mixins/with_permissions.ts'
import { permissions, Role } from './fixtures/models.ts'

/**
 * A schema class booted by its own decorators, as generated by the
 * Lucid schema generator, with a loosely typed permissions column.
 */
class RoleSchema extends BaseModel {
  static table = 'roles'

  @column({ isPrimary: true })
  declare id: number

  @column()
  declare name: string

  @column()
  declare permissions: unknown
}

/**
 * Role model built on top of an already booted schema class.
 */
class SchemaRole extends compose(RoleSchema, withPermissions(permissions)) {
  static table = 'roles'
}

/**
 * A subclass of a model using the mixin.
 */
class SpecialRole extends Role {
  static table = 'roles'
}
import { setupDatabase } from './helpers.ts'

type Database = Awaited<ReturnType<typeof setupDatabase>>

/**
 * Reads the raw "permissions" column of a role.
 */
async function storedPermissions(database: Database, id: number): Promise<unknown> {
  const row = await database.db.from('roles').where('id', id).firstOrFail()
  return row.permissions
}

test.group('withPermissions', (group) => {
  let database: Database

  group.each.setup(async () => {
    database = await setupDatabase()
    return () => database.close()
  })

  test('stores an empty list when a row is created without permissions', async ({ assert }) => {
    const role = await Role.create({ name: 'viewer' })

    assert.deepEqual(role.permissions, [])
    assert.equal(await storedPermissions(database, role.id), '[]')
    assert.deepEqual(await role.getGrants(), [])
    assert.deepEqual(await role.getPermissions(), [])
  })

  test('gives permissions and persists them as JSON', async ({ assert }) => {
    const role = await Role.create({ name: 'editor' })
    await role.givePermission('product.create')
    await role.givePermissions(['product.update', 'billing.*'])

    assert.deepEqual(role.permissions, ['product.create', 'product.update', 'billing.*'])
    assert.equal(
      await storedPermissions(database, role.id),
      '["product.create","product.update","billing.*"]'
    )

    const fresh = await Role.findOrFail(role.id)
    assert.deepEqual(fresh.permissions, ['product.create', 'product.update', 'billing.*'])
    assert.deepEqual(await fresh.getPermissions(), [
      'product.create',
      'product.update',
      'billing.refund',
    ])
    assert.isTrue(await fresh.hasPermission('billing.refund'))
    assert.isFalse(await fresh.hasPermission('product.delete'))
  })

  test('gives permissions idempotently', async ({ assert }) => {
    const role = await Role.create({ name: 'editor' })
    await role.givePermissions(['product.create', 'product.create'])

    const { queries } = await database.track(() => role.givePermissions(['product.create']))

    assert.lengthOf(queries, 0)
    assert.deepEqual(role.permissions, ['product.create'])
    assert.equal(await storedPermissions(database, role.id), '["product.create"]')
  })

  test('gives permissions to a row that is not persisted yet', async ({ assert }) => {
    const role = new Role()
    role.name = 'draft'
    await role.givePermission('billing.refund')

    assert.isTrue(role.$isPersisted)
    assert.equal(await storedPermissions(database, role.id), '["billing.refund"]')
  })

  test('accepts inactive keys and every wildcard kind', async ({ assert }) => {
    const role = await Role.create({ name: 'admin' })
    await role.givePermissions(['product.archive', '*', 'admin.*', 'admin.user.*', 'product.*'])

    assert.deepEqual(role.permissions, [
      'product.archive',
      '*',
      'admin.*',
      'admin.user.*',
      'product.*',
    ])
  })

  test('throws E_UNKNOWN_PERMISSION on {title} and writes nothing')
    .with([
      { title: 'a typo', value: 'product.craete' },
      { title: 'an alias', value: 'product.remove' },
      { title: 'an unknown resource wildcard', value: 'order.*' },
      { title: 'an unknown prefix wildcard', value: 'staff:*' },
      { title: 'a malformed value', value: 'product' },
    ])
    .run(async ({ assert }, { value }) => {
      const role = await Role.create({ name: 'editor' })
      await role.givePermission('product.create')

      const write = role.givePermissions as (grants: string[]) => Promise<void>
      const sync = role.syncPermissions as (grants: string[]) => Promise<void>
      const revoke = role.revokePermissions as (grants: string[]) => Promise<void>

      for (const operation of [write, sync, revoke]) {
        try {
          await operation.call(role, ['billing.refund', value])
          assert.fail(`Expected "${value}" to be rejected`)
        } catch (error) {
          assert.instanceOf(error, E_UNKNOWN_PERMISSION)
          assert.equal((error as { code: string }).code, 'E_UNKNOWN_PERMISSION')
          assert.equal(
            (error as Error).message,
            `Unknown permission "${value}". Expected a defined permission key or wildcard`
          )
          assert.equal((error as { value: unknown }).value, value)
        }
      }

      assert.deepEqual(role.permissions, ['product.create'])
      assert.equal(await storedPermissions(database, role.id), '["product.create"]')
    })

  test('syncs permissions by replacing the stored list', async ({ assert }) => {
    const role = await Role.create({ name: 'editor' })
    await role.givePermissions(['product.create', 'product.update'])
    await role.syncPermissions(['billing.refund', 'billing.refund', 'admin.*'])

    assert.deepEqual(role.permissions, ['billing.refund', 'admin.*'])
    assert.equal(await storedPermissions(database, role.id), '["billing.refund","admin.*"]')

    await role.syncPermissions([])
    assert.equal(await storedPermissions(database, role.id), '[]')
  })

  test('revokes permissions idempotently', async ({ assert }) => {
    const role = await Role.create({ name: 'editor' })
    await role.givePermissions(['product.create', 'product.update', 'billing.refund'])

    await role.revokePermission('product.update')
    await role.revokePermissions(['billing.refund', 'product.delete'])

    assert.deepEqual(role.permissions, ['product.create'])
    assert.equal(await storedPermissions(database, role.id), '["product.create"]')

    const { queries } = await database.track(() => role.revokePermission('product.update'))
    assert.lengthOf(queries, 0)
    assert.deepEqual(role.permissions, ['product.create'])
  })

  test('removes stored aliases when revoking the canonical key', async ({ assert }) => {
    await database.db
      .table('roles')
      .insert({ name: 'legacy', permissions: '["product.remove","product.create"]' })
    const role = await Role.findByOrFail('name', 'legacy')

    assert.deepEqual(await role.getPermissions(), ['product.create', 'product.delete'])

    await role.revokePermission('product.delete')

    assert.deepEqual(role.permissions, ['product.create'])
    assert.equal(await storedPermissions(database, role.id), '["product.create"]')
  })

  test('removes stored namespace aliases when revoking the canonical grant', async ({ assert }) => {
    await database.db
      .table('roles')
      .insert({ name: 'legacy', permissions: '["backoffice.*","backoffice.user.ban"]' })
    const role = await Role.findByOrFail('name', 'legacy')

    await role.revokePermission('admin.*')
    assert.deepEqual(role.permissions, ['backoffice.user.ban'])

    await role.revokePermission('admin.user.ban')
    assert.deepEqual(role.permissions, [])
  })

  test('does not narrow a stored wildcard when revoking a key', async ({ assert }) => {
    const role = await Role.create({ name: 'editor' })
    await role.givePermission('product.*')
    await role.revokePermission('product.create')

    assert.deepEqual(role.permissions, ['product.*'])
    assert.isTrue(await role.hasPermission('product.create'))

    await role.revokePermission('product.*')
    assert.deepEqual(role.permissions, [])
    assert.isFalse(await role.hasPermission('product.create'))
  })

  test('consumes {title}')
    .with([
      { title: 'a JSON string', raw: '["billing.refund"]', expected: ['billing.refund'] },
      { title: 'an empty JSON array', raw: '[]', expected: [] },
      { title: 'malformed JSON', raw: '{oops', expected: [] },
      { title: 'a JSON object', raw: '{"a":1}', expected: [] },
      { title: 'non string items', raw: '["billing.refund",1,null]', expected: ['billing.refund'] },
    ])
    .run(async ({ assert }, { raw, expected }) => {
      await database.db.table('roles').insert({ name: 'raw', permissions: raw })
      const role = await Role.findByOrFail('name', 'raw')
      assert.deepEqual(role.permissions, expected)
    })

  test('consumes an already parsed array and null', ({ assert }) => {
    const column = Role.$getColumn('permissions')!

    assert.deepEqual(column.consume!(['billing.refund'], 'permissions', new Role()), [
      'billing.refund',
    ])
    assert.deepEqual(column.consume!(null, 'permissions', new Role()), [])
    assert.deepEqual(column.consume!(undefined, 'permissions', new Role()), [])
    assert.equal(column.prepare!(['a.b'], 'permissions', new Role()), '["a.b"]')
    assert.equal(column.prepare!(null, 'permissions', new Role()), '[]')
  })

  test('registers the column on top of an already booted schema class', async ({ assert }) => {
    assert.isTrue(RoleSchema.booted)

    const role = await SchemaRole.create({ name: 'editor' })
    await role.givePermissions(['billing.refund'])

    assert.equal(await storedPermissions(database, role.id), '["billing.refund"]')
    const fresh = await SchemaRole.findOrFail(role.id)
    assert.deepEqual(fresh.permissions, ['billing.refund'])
    assert.deepEqual(await fresh.getPermissions(), ['billing.refund'])
  })

  test('keeps the column on subclasses', async ({ assert }) => {
    const role = await SpecialRole.create({ name: 'special' })
    await role.givePermission('admin.*')

    const fresh = await SpecialRole.findOrFail(role.id)
    assert.deepEqual(fresh.permissions, ['admin.*'])
    assert.deepEqual(await fresh.getPermissions(), ['admin.user.ban', 'admin.user.impersonate'])
  })

  test('serializes permissions as an array', async ({ assert }) => {
    const role = await Role.create({ name: 'editor' })
    await role.givePermission('billing.refund')

    assert.deepEqual(role.serialize(), {
      id: role.id,
      name: 'editor',
      permissions: ['billing.refund'],
    })
  })
})
